using Effect=PF_Err(*)(PF_Cmd,PF_InData*,PF_OutData*,PF_ParamDef*[],PF_LayerDef*,void*);
constexpr int W=32,H=18;static PF_ParamDef g_params[OLMDIRECTIONALBLUR_NUM_PARAMS];static PF_EffectWorld*g_input=nullptr,*g_output=nullptr;static int g_pre=0,g_layer=0,g_out=0,g_in_checkin=0,g_noise_checkin=0,g_param_out=0,g_param_in=0;static bool g_preserve=false;
