template<class P>static void Fill(std::vector<unsigned char>&b,int rb,const std::vector<unsigned char>&rgba){for(int y=0;y<H;++y)for(int x=0;x<W;++x){int z=(y*W+x)*4;P*p=reinterpret_cast<P*>(b.data()+(size_t)y*rb)+x;if constexpr(sizeof(P)==sizeof(PF_Pixel8))*p={(A_u_char)rgba[z+3],(A_u_char)rgba[z],(A_u_char)rgba[z+1],(A_u_char)rgba[z+2]};else if constexpr(sizeof(P)==sizeof(PF_Pixel16))*p={(A_u_short)((rgba[z+3]*32768+127)/255),(A_u_short)((rgba[z]*32768+127)/255),(A_u_short)((rgba[z+1]*32768+127)/255),(A_u_short)((rgba[z+2]*32768+127)/255)};else *p={rgba[z+3]/255.f,rgba[z]/255.f,rgba[z+1]/255.f,rgba[z+2]/255.f};}}
struct Result{PF_Err pre_err,render_err;std::vector<unsigned char>input,output;PF_EffectWorld ih,oh;int pre,layer,out,input_checkin,noise_checkin,param_out,param_in;bool preserve,rects;};
template<class P>static Result Run(Effect effect,short depth,const std::vector<unsigned char>&rgba,bool mutate){int pad=depth==8?12:depth==16?16:32,rb=W*(int)sizeof(P)+pad;std::vector<unsigned char>ib((size_t)rb*H,0xa5),ob((size_t)rb*H,0xee);Fill<P>(ib,rb,rgba);if(mutate)ib[0]^=1;PF_EffectWorld iw{},ow{};iw.data=reinterpret_cast<PF_PixelPtr>(ib.data());iw.rowbytes=rb;iw.width=W;iw.height=H;iw.extent_hint={0,0,W,H};ow=iw;ow.data=reinterpret_cast<PF_PixelPtr>(ob.data());Params(iw);g_input=&iw;g_output=&ow;g_depth=depth;g_pre=g_layer=g_out=g_in_checkin=g_noise_checkin=g_param_out=g_param_in=0;g_preserve=false;SPBasicSuite basic{};basic.AcquireSuite=Acquire;basic.ReleaseSuite=Release;PF_InData in{};PF_OutData out{};in.effect_ref=reinterpret_cast<PF_ProgPtr>(1);in.pica_basicP=&basic;in.current_time=7;in.time_step=1;in.time_scale=24;in.downsample_x={1,1};in.downsample_y={1,1};in.inter.checkout_param=Checkout;in.inter.checkin_param=Checkin;PF_PreRenderInput pi{};pi.bitdepth=depth;pi.output_request.rect={0,0,W,H};PF_PreRenderOutput po{};PF_PreRenderCallbacks pcb{};pcb.checkout_layer=Pre;PF_PreRenderExtra pe{&pi,&po,&pcb};PF_Err pre=effect(PF_Cmd_SMART_PRE_RENDER,&in,&out,nullptr,nullptr,&pe);bool rects=po.result_rect.left==0&&po.result_rect.top==0&&po.result_rect.right==W&&po.result_rect.bottom==H&&po.max_result_rect.left==0&&po.max_result_rect.top==0&&po.max_result_rect.right==W&&po.max_result_rect.bottom==H;PF_SmartRenderInput si{};si.bitdepth=depth;si.pre_render_data=po.pre_render_data;PF_SmartRenderCallbacks cb{};cb.checkout_layer_pixels=Layer;cb.checkout_output=Output;cb.checkin_layer_pixels=CheckLayer;PF_SmartRenderExtra se{&si,&cb};PF_Err render=pre?pre:effect(PF_Cmd_SMART_RENDER,&in,&out,nullptr,nullptr,&se);if(po.delete_pre_render_data_func)po.delete_pre_render_data_func(po.pre_render_data);return{pre,render,ib,ob,iw,ow,g_pre,g_layer,g_out,g_in_checkin,g_noise_checkin,g_param_out,g_param_in,g_preserve,rects};}
static bool Pad(const std::vector<unsigned char>&b,int depth,unsigned char value){int ps=depth==8?4:depth==16?8:16,pad=depth==8?12:depth==16?16:32,rb=W*ps+pad;for(int y=0;y<H;++y)for(int x=W*ps;x<rb;++x)if(b[(size_t)y*rb+x]!=value)return false;return true;}
