int main(int argc,char**argv){if(argc!=3)return 2;std::ifstream f(argv[2],std::ios::binary);std::vector<unsigned char>rgba((std::istreambuf_iterator<char>(f)),{});if(rgba.size()!=W*H*4)return 3;void*h=dlopen(argv[1],RTLD_NOW|RTLD_LOCAL);if(!h){std::fprintf(stderr,"%s\n",dlerror());return 4;}auto installed=reinterpret_cast<Effect>(dlsym(h,"EffectMain"));if(!installed)return 5;int pass=0,total=0;auto row=[&](const char*n,bool ok,const Result&s,const Result&i){++total;if(ok)++pass;std::printf("%s pass=%d source=%d/%d installed=%d/%d\n",n,ok,s.pre_err,s.render_err,i.pre_err,i.render_err);};for(int depth:{8,16,32}){auto s=Dispatch(SourceBuiltOLMDirectionalBlurEffectMain,depth,rgba,false),i=Dispatch(installed,depth,rgba,false);bool life=s.pre==2&&s.layer==2&&s.out==1&&s.input_checkin==1&&s.noise_checkin==0&&s.param_out==21&&s.param_in==21&&s.preserve&&s.rects;bool ilife=i.pre==s.pre&&i.layer==s.layer&&i.out==s.out&&i.input_checkin==s.input_checkin&&i.noise_checkin==s.noise_checkin&&i.param_out==s.param_out&&i.param_in==s.param_in&&i.preserve&&i.rects;char n[80];std::snprintf(n,sizeof(n),"POS dual_side_type2_pf%d",depth);row(n,s.pre_err==0&&s.render_err==0&&i.pre_err==0&&i.render_err==0&&s.input==i.input&&s.output==i.output&&Pad(s.output,depth,0xee)&&Pad(i.output,depth,0xee)&&life&&ilife,s,i);s=Dispatch(SourceBuiltOLMDirectionalBlurEffectMain,depth,rgba,true);i=Dispatch(installed,depth,rgba,true);int ps=depth==8?4:depth==16?8:16,pad=depth==8?12:depth==16?16:32;std::vector<unsigned char>untouched((size_t)(W*ps+pad)*H,0xee);std::snprintf(n,sizeof(n),"NEG source_bit_flip_pf%d",depth);row(n,s.pre_err==0&&s.render_err==PF_Err_BAD_CALLBACK_PARAM&&i.pre_err==0&&i.render_err==s.render_err&&s.output==untouched&&i.output==untouched,s,i);}std::printf("SUMMARY pass=%d total=%d\n",pass,total);dlclose(h);return pass==total?0:6;}
